contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address token, address to, uint v, uint extra) public {
        require(extra <= 1);
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vs = new uint[](1 + extra);
        vs[0] = v;
        bool reverted;
        bool ok;
        if (extra == 0) {
            ok = c.transfer(from, token, tos, vs);
            reverted = false;
        } else {
            try c.transfer(from, token, tos, vs) returns (bool r) {
                ok = r;
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        if (extra == 0) {
            assert(!reverted && ok);
        } else {
            assert(reverted);
        }
    }
    receive() external payable {}
}

